#include <iostream>

int main() {
    long long mib{0};
    long long rateKbit{0};
    long long overheadPercent{0};
    if (!(std::cin >> mib >> rateKbit >> overheadPercent)) {
        std::cout << "invalid\n";
        return 0;
    }
    std::cin >> std::ws;
    if (!std::cin.eof() || mib < 0 || mib > 1000000 || rateKbit < 1 || rateKbit > 1000000 || overheadPercent < 0 || overheadPercent > 100) {
        std::cout << "invalid\n";
        return 0;
    }
    constexpr long long bytesPerMiB{1024LL * 1024};
    constexpr long long bitsPerByte{8};
    constexpr long long bitsPerKbit{1000};
    long long numerator = mib * bytesPerMiB * bitsPerByte * (100 + overheadPercent);
    long long denominator = 100LL * rateKbit * bitsPerKbit;
    long long seconds = numerator / denominator + (numerator % denominator != 0);
    std::cout << seconds << ' ' << seconds / 60 << ' ' << seconds % 60 << '\n';
    return 0;
}

