#include <iostream>

int main() {
    int stock{0};
    if (!(std::cin >> stock)) {
        std::cout << "invalid\n";
        return 0;
    }
    std::cin >> std::ws;
    if (!std::cin.eof() || stock < 0 || stock > 100) {
        std::cout << "invalid\n";
        return 0;
    }
    int snapshot = stock;
    int& alias = stock;
    int* selected = &stock;
    int issued = stock >= 3 ? 3 : stock;
    alias -= issued;
    std::cout << "before=" << snapshot << '\n';
    std::cout << "after=" << *selected << '\n';
    std::cout << "issued=" << issued << '\n';
    std::cout << "same_object=" << (&alias == selected) << '\n';
    return 0;
}

